.flow-title{font-family:'Space Grotesk',sans-serif;font-size:15.5px;font-weight:600;color:var(--text);margin-bottom:4px}
.flow-text{font-size:14px;line-height:1.6;color:var(--text2)}
.doc-table-wrap{border:1px solid rgba(255,255,255,.08);border-radius:18px;overflow:hidden;margin-bottom:26px;overflow-x:auto}
