.stat-grid{display:grid;grid-template-columns:1fr;gap:1px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.08);border-radius:18px;overflow:hidden;margin-bottom:36px}
@media(min-width:640px){.stat-grid{grid-template-columns:repeat(3,1fr)}}
.stat-card{background:#080807;padding:24px 22px}
.stat-value{font-family:'Space Grotesk',sans-serif;font-size:30px;font-weight:700;color:var(--gold);line-height:1;margin-bottom:8px}
.stat-label{font-size:13.5px;color:var(--text2)}
.rule-list{display:flex;flex-direction:column;gap:11px;margin-bottom:32px}
.rule-item{display:flex;gap:12px;background:#0D0C0A;border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:16px 20px;align-items:flex-start}
.rule-item::before{content:'◆';color:var(--gold);flex-shrink:0;margin-top:2px}
.rule-text{font-size:14.5px;line-height:1.6;color:var(--text)}
.flow{display:flex;flex-direction:column;gap:1px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.08);border-radius:18px;overflow:hidden;margin-bottom:28px}
.flow-row{background:#080807;padding:20px 24px;display:flex;gap:18px;align-items:flex-start}
.flow-num{font-family:'Space Grotesk',sans-serif;font-size:13px;font-weight:700;color:#000;background:var(--gold);width:26px;height:26px;border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.flow-title{font-family:'Space Grotesk',sans-serif;font-size:15.5px;font-weight:600;color:var(--text);margin-bottom:4px}
.flow-text{font-size:14px;line-height:1.65;color:var(--text2)}
.tech-card{display:flex;gap:16px;align-items:flex-start;background:#0D0C0A;border:1px solid rgba(255,255,255,.1);border-radius:16px;padding:20px 22px;margin:0 0 28px}
.tech-icon{width:32px;height:32px;border-radius:10px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.tech-icon svg{width:16px;height:16px;stroke:var(--text2);fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.tech-label{font-family:'Space Grotesk',sans-serif;font-size:11px;font-weight:600;letter-spacing:.13em;text-transform:uppercase;color:var(--text2);margin-bottom:6px}
.tech-text{font-size:14.5px;line-height:1.7;color:var(--text2)}
.doc-cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:36px;padding-top:32px;border-top:1px solid rgba(255,255,255,.08)}
.btn-gold{background:var(--gold);color:#000;font-family:'Space Grotesk',sans-serif;font-size:14.5px;font-weight:700;padding:14px 28px;border-radius:12px;text-decoration:none}
.btn-gold:hover{background:var(--gold2);color:#000}
.btn-ghost{border:1px solid rgba(255,255,255,.14);color:var(--text);font-family:'Space Grotesk',sans-serif;font-size:14.5px;font-weight:600;padding:13px 28px;border-radius:12px;text-decoration:none;transition:border-color .2s,color .2s}
.btn-ghost:hover{border-color:rgba(255,184,0,.4);color:var(--gold)}
.next-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;margin-top:40px}
.next-card{display:block;background:#0D0C0A;border:1px solid rgba(255,255,255,.08);border-radius:16px;padding:20px 22px;text-decoration:none;transition:border-color .2s}
.next-card:hover{border-color:rgba(255,184,0,.35)}
.next-kicker{font-size:11px;font-family:'Space Grotesk',sans-serif;letter-spacing:.12em;text-transform:uppercase;color:var(--text3);margin-bottom:8px}
.next-title{font-family:'Space Grotesk',sans-serif;font-size:16px;font-weight:600;color:var(--text)}

input::placeholder{color:var(--text3)}
.start-modal-opt.opt-site{background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.1)}
article{min-width:0;max-width:74ch;padding-bottom:60px}
.lede{font-size:18px;color:var(--text2);margin-bottom:24px}
.search-box{display:flex;align-items:center;gap:12px;background:#0D0C0A;border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:0 18px;margin-bottom:28px;transition:border-color .2s}
.search-box:focus-within{border-color:rgba(255,184,0,.4)}
.search-box svg{width:17px;height:17px;flex-shrink:0;stroke:var(--text2);fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.search-box input{flex:1;background:transparent;border:0;outline:0;color:var(--text);font-family:'Inter',sans-serif;font-size:15px;padding:14px 0}
.faq-group{margin-bottom:28px}
.faq-group h2{font-family:'Space Grotesk',sans-serif;font-size:19px;font-weight:600;color:var(--text);margin-bottom:14px;letter-spacing:.01em;scroll-margin-top:88px}
.faq-items{display:flex;flex-direction:column;gap:10px}
.faq-item{background:#0D0C0A;border:1px solid rgba(255,255,255,.08);border-radius:14px;overflow:hidden;transition:border-color .2s}
.faq-item.open{border-color:rgba(255,184,0,.3)}
.faq-btn{cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:18px;padding:17px 20px;width:100%;background:none;border:none;text-align:left;font-family:'Space Grotesk',sans-serif;font-size:15px;font-weight:600;color:var(--text)}
.faq-sign{color:var(--gold);font-size:18px;flex-shrink:0;line-height:1}
.faq-body{padding:0 20px 18px;font-size:14.5px;line-height:1.7;color:var(--text2);display:none}
.faq-item.open .faq-body{display:block}
.empty-note{display:none;border:1px dashed rgba(255,255,255,.12);border-radius:16px;padding:36px;text-align:center;color:var(--text2)}
.empty-note.show{display:block}
.help-strip{background:linear-gradient(135deg,rgba(255,184,0,.1),rgba(255,184,0,.03));border:1px solid rgba(255,184,0,.22);border-radius:20px;padding:28px;margin-top:36px;display:flex;gap:20px;flex-wrap:wrap;align-items:center;justify-content:space-between}
.help-strip h2{font-family:'Space Grotesk',sans-serif;font-size:21px;font-weight:700;margin-bottom:6px}
.help-strip p{color:var(--text2);max-width:48ch}
.help-buttons{display:flex;gap:10px;flex-wrap:wrap}
