.btn-gold:hover{background:var(--gold2);color:#000}
.btn-ghost{border:1px solid rgba(255,255,255,.14);color:var(--text);font-family:'Space Grotesk',sans-serif;font-size:14px;font-weight:600;padding:11px 22px;border-radius:11px;text-decoration:none;transition:border-color .2s,color .2s}
.btn-ghost:hover{border-color:rgba(255,184,0,.4);color:var(--gold)}

